                                  // inverse zoom around the anchor\n\t\t\t\tvec2 uv = p + anchor - vec2(offsetX, offsetY);  // re-anchor + pan\n\t\t\t\tuv = clamp(uv, 0.0, 1.0);                       // clamp = no empty edges\n\t\t\t\tgl_FragColor = TEXTURE2D(tInput, uv);\n\t\t\t}",update:(t,e)=>{const n=e&&(e.kb||e.kenburns);n&&(t.scale&&(t.scale.value=n.scale??1),t.rot&&(t.rot.value=n.rot??0),t.offsetX&&(t.offsetX.value=n.offsetX??0),t.offsetY&&(t.offsetY.value=n.offsetY??0),t.anchorX&&(t.anchorX.value=n.anchorX??.5),t.anchorY&&(t.anchorY.value=n.anchorY??.5))}}),SR7.F.regPass("overleaving",{kind:"shader",role:"filter",inputs:()=>[{name:"tInput",source:"chain"},{name:"tLeaving",source:"leaving:repeat"}],frag:"uniform sampler2D tInput;\nuniform sampler2D tLeaving;\nvarying vec2 vUv;\nvoid main(){\n\tvec4 e = TEXTURE2D(tInput, vUv);\n\tvec3 l = TEXTURE2D(tLeaving, vUv).rgb;\n\tfloat a = clamp(e.a, 0.0, 1.0);\n\tgl_FragColor = vec4(e.rgb + l * (1.0 - a), 1.0);\n}",uniforms:{tInput:{default:null},tLeaving:{default:null}}}),SR7.F.regPass("crossfade",{kind:"shader",role:"filter",inputs:()=>[{name:"tComingRT",source:"chain"}],uniforms:{src1:{default:null},src2:{default:null},inOff:{default:[0,0]},inScale:{default:[1,1]},inRot:{default:0},inOp:{default:0},outOff:{default:[0,0]},outScale:{default:[1,1]},outRot:{default:0},outOp:{default:0},aspect:{default:1},comingTop:{default:1},hasLeaving:{default:1},alphaMode:{default:0},grid:{default:[1,1]},gridOut:{default:[1,1]},stagger:{default:0},staggerFrom:{default:0},easeId:{default:0},easeIdOut:{default:0},inR:{default:0},outR:{default:0},varSeed:{default:0},varM:{default:new Float32Array(30)},varR:{default:new Float32Array(20)},varTex:{default:null},mbAmt:{default:0},mbTaps:{default:12},through:{default:0},throughColor:{default:[0,0,0]},thruIn:{default:.3333},flt:{default:0},fltAmt:{default:0},fltGray:{default:0},fltBright:{default:1},fltSepia:{default:0},fltContrast:{default:1},fltInvert:{default:0},fltSat:{default:1},fltBlur:{default:0},fltBlurTaps:{default:24},tComingRT:{default:null},dbl:{default:0},dblDrift:{default:.2},dblGhostDrift:{default:.4},dblGhostDark:{default:.4},dblEdge:{default:.008}},frag:"\n\t\t\t//LEAN is set by the core runner, which lists exactly the blocks its transition needs. A caller that passes NO\n\t\t\t//defines (any addon building {type:\"crossfade\"} itself, e.g. transitionpack's layer reveals) gets the FULL\n\t\t\t//shader — same behaviour as before this pass replaced the monolith, so no addon has to be touched.\n\t\t\t#ifndef LEAN\n\t\t\t#define GRID\n\t\t\t#define GRIDN\n\t\t\t#define VAR\n\t\t\t#define EF1\n\t\t\t#define EF2\n\t\t\t#define EF3\n\t\t\t#define EF4\n\t\t\t#define EF5\n\t\t\t#define EF6\n\t\t\t#define EF7\n\t\t\t#define EF8\n\t\t\t#define EF9\n\t\t\t#define SF_RANDOM\n\t\t\t#define VARTEX\n\t\t\t#define VS0\n\t\t\t#define VS1\n\t\t\t#define VS2\n\t\t\t#define VS3\n\t\t\t#define VS4\n\t\t\t#define VS5\n\t\t\t#define VS6\n\t\t\t#define VS7\n\t\t\t#define VS8\n\t\t\t#define VS9\n\t\t\t#define MB\n\t\t\t#define THRU\n\t\t\t#define FILTER\n\t\t\t#define FBLUR\n\t\t\t#define DOUBLE\n\t\t\t#endif\n\t\t\tvarying vec2 vUv;\n\t\t\tuniform sampler2D src1, src2;\n\t\t\tuniform float progress, inRot, outRot, inOp, outOp, aspect, comingTop, hasLeaving, alphaMode;\n\t\t\tuniform vec2 inOff, inScale, outOff, outScale;\n\t\t\t#ifdef DOUBLE\n\t\t\tuniform float dbl, dblDrift, dblGhostDrift, dblGhostDark, dblEdge;\n\t\t\t#endif\n\t\t\t//Neighbour sweep bounds. GLSL ES 1.00 needs CONSTANT loop bounds, and FXC unrolls the whole thing — at the old\n\t\t\t//fixed 5 that is 11x11 = 121 copies of the cell body, which is what makes Boxes take seconds to compile on\n\t\t\t//Firefox/ANGLE. The runner measures the travel this frame actually needs and bakes it in, PER AXIS: a cell that\n\t\t\t//flies 5 columns but no rows cannot reach a pixel 5 rows away, so that sweep is 11x1, not 11x11.\n\t\t\t#ifndef GRIDRX\n\t\t\t#define GRIDRX 5\n\t\t\t#endif\n\t\t\t#ifndef GRIDRY\n\t\t\t#define GRIDRY 5\n\t\t\t#endif\n\t\t\t//Tap counts multiply the sweep above: motion blur re-runs the WHOLE cell composite per tap, so a 16-tap bound\n\t\t\t//over a 55-cell sweep is 880 unrolled cell bodies. The runner already budgets the taps down (mbTapsFor caps\n\t\t\t//them against the cell count) — it just never told the compiler, which kept unrolling the full 16 and 24.\n\t\t\t#ifndef MBTAPS\n\t\t\t#define MBTAPS 16\n\t\t\t#endif\n\t\t\t#ifndef FBTAPS\n\t\t\t#define FBTAPS 24\n\t\t\t#endif\n\t\t\t#ifdef GRID\n\t\t\tuniform vec2 grid, gridOut;\n\t\t\tuniform float stagger, staggerFrom, easeId, easeIdOut, inR, outR;\n\t\t\t#endif\n\t\t\t#ifdef VAR\n\t\t\tuniform float varSeed;\n\t\t\tuniform vec3 varM[10];\n\t\t\tuniform vec2 varR[10];\n\t\t\t#ifdef VARTEX\n\t\t\tuniform sampler2D varTex;\n\t\t\t#endif\n\t\t\t#endif\n\t\t\t#ifdef MB\n\t\t\tuniform float mbAmt, mbTaps;\n\t\t\t#endif\n\t\t\t#ifdef THRU\n\t\t\tuniform float through, thruIn;\n\t\t\tuniform vec3 throughColor;\n\t\t\t#endif\n\t\t\t#ifdef FILTER\n\t\t\tuniform float flt, fltAmt, fltGray, fltBright, fltSepia, fltContrast, fltInvert, fltSat;\n\t\t\t#endif\n\t\t\t#ifdef FBLUR\n\t\t\tuniform float fltBlur, fltBlurTaps;\n\t\t\t#endif\n\t\t\t#ifdef COMINGSRC\n\t\t\tuniform sampler2D tComingRT;\n\t\t\t#endif\n\n\t\t\tmat2 rot2(float a){ float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }\n\t\t\t//inverse-rotate a centre-relative coord, aspect-corrected (UV is square, the frame is not)\n\t\t\tvec2 unrotate(vec2 q, float ang, float asp){ q.x *= asp; q = rot2(-ang) * q; q.x /= asp; return q; }\n\t\t\t#if defined(VAR) || defined(GRID)\n\t\t\tfloat hash21(vec2 c){ return fract(sin(dot(c, vec2(12.9898, 78.233))) * 43758.5453); }\n\t\t\t#endif\n\n\t\t\t#ifdef VAR\n\t\t\t//Per-box VARIATION: mode 0 -> the plain uniform (zero cost); 1 -> {min,max} per-cell hash, re-seeded per\n\t\t\t//transition; 2 -> literal array in the 64x1 varTex, cycled by box index (column-major, rows TOP-down).\n\t\t\tfloat varV(vec3 m, vec2 rr, float salt, float base, vec2 cell, vec2 g) {\n\t\t\t\tif (m.x < 0.5) return base;\n\t\t\t\t#ifndef VARTEX\n\t\t\t\t//No [a,b,..] literal list anywhere in this transition, only {min,max} randoms — so the 64x1 lookup, its\n\t\t\t\t//index maths and the sampler never reach the binary. This runs once per varying slot per unrolled cell.\n\t\t\t\treturn mix(rr.x, rr.y, hash21(cell + vec2(varSeed + salt * 7.31, varSeed * 1.7 + salt)));\n\t\t\t\t#else\n\t\t\t\tif (m.x < 1.5) return mix(rr.x, rr.y, hash21(cell + vec2(varSeed + salt * 7.31, varSeed * 1.7 + salt)));\n\t\t\t\tfloat i = mod(cell.x * g.y + (g.y - 1.0 - cell.y), max(m.z, 1.0));\n\t\t\t\tvec4 t = TEXTURE2D(varTex, vec2((m.y + i + 0.5) / 64.0, 0.5));\n\t\t\t\treturn mix(rr.x, rr.y, (t.r * 65280.0 + t.g * 255.0) / 65535.0);\n\t\t\t\t#endif\n\t\t\t}\n\t\t\t//The 5 per-side variation params in one bundle. A slot is only COMPILED when that param actually carries a\n\t\t\t//{min,max} / [a,b,..] string — the runner knows which from _varSlots. A slot left out passes its base value\n\t\t\t//through, exactly as varV's mode-0 fast path did, but without the texture fetch and hash in the binary.\n\t\t\tvoid varSet(vec2 k, vec2 g, float s0, vec2 offB, float rotB, vec2 sclB, out vec2 offK, out float rotK, out vec2 sclK) {\n\t\t\t\toffK = offB; rotK = rotB; sclK = sclB;\n\t\t\t\tif (s0 < 0.5) {\n\t\t\t\t\t#ifdef VS0\n\t\t\t\t\toffK.x = varV(varM[0], varR[0], 0.0, offB.x, k, g);\n\t\t\t\t\t#endif\n\t\t\t\t\t#ifdef VS1\n\t\t\t\t\toffK.y = varV(varM[1], varR[1], 1.0, offB.y, k, g);\n\t\t\t\t\t#endif\n\t\t\t\t\t#ifdef VS2\n\t\t\t\t\trotK   = varV(varM[2], varR[2], 2.0, rotB, k, g);\n\t\t\t\t\t#endif\n\t\t\t\t\t#ifdef VS3\n\t\t\t\t\tsclK.x = varV(varM[3], varR[3], 3.0, sclB.x, k, g);\n\t\t\t\t\t#endif\n\t\t\t\t\t#ifdef VS4\n\t\t\t\t\tsclK.y = varV(varM[4], varR[4], 4.0, sclB.y, k, g);\n\t\t\t\t\t#endif\n\t\t\t\t} else {\n\t\t\t\t\t#ifdef VS5\n\t\t\t\t\toffK.x = varV(varM[5], varR[5], 5.0, offB.x, k, g);\n\t\t\t\t\t#endif\n\t\t\t\t\t#ifdef VS6\n\t\t\t\t\toffK.y = varV(varM[6], varR[6], 6.0, offB.y, k, g);\n\t\t\t\t\t#endif\n\t\t\t\t\t#ifdef VS7\n\t\t\t\t\trotK   = varV(varM[7], varR[7], 7.0, rotB, k, g);\n\t\t\t\t\t#endif\n\t\t\t\t\t#ifdef VS8\n\t\t\t\t\tsclK.x = varV(varM[8], varR[8], 8.0, sclB.x, k, g);\n\t\t\t\t\t#endif\n\t\t\t\t\t#ifdef VS9\n\t\t\t\t\tsclK.y = varV(varM[9], varR[9], 9.0, sclB.y, k, g);\n\t\t\t\t\t#endif\n\t\t\t\t}\n\t\t\t}\n\t\t\t#endif\n\n\t\t\t#ifdef GRID\n\t\t\t//normalized 0..1 stagger delay — gsap's distribute EXACTLY: start/end origins sit HALF A CELL outside the\n\t\t\t//corner (-0.5 / g-0.5), center/edges the exact centre, ratios (d-min)/(max-min) with min = nearest cell.\n\t\t\tfloat cellDelayN(vec2 cell, vec2 g) {\n\t\t\t\tif (g.x * g.y < 2.0) return 0.0;\n\t\t\t\t#ifdef SF_RANDOM\n\t\t\t\tif (staggerFrom > 3.5) return hash21(cell);\n\t\t\t\t#endif\n\t\t\t\t//UV y runs upwards, so cell (0,0) is the BOTTOM-left one — but \"start\" is the TOP-left cell (gsap's\n\t\t\t\t//row-major order; the 3D pass flips to the same top-down lattice). Only start/end feel it: center and\n\t\t\t\t//edges are symmetric in y.\n\t\t\t\tcell.y = g.y - 1.0 - cell.y;\n\t\t\t\t#ifdef SF_START\n\t\t\t\tvec2 origin = vec2(-0.5);\n\t\t\t\t#elif defined(SF_END)\n\t\t\t\tvec2 origin = g - 0.5;\n\t\t\t\t#elif defined(SF_MID)\n\t\t\t\tvec2 origin = (g - 1.0) * 0.5;\n\t\t\t\t#else\n\t\t\t\tvec2 origin = staggerFrom < 0.5 ? vec2(-0.5) : staggerFrom < 1.5 ? g - 0.5 : (g - 1.0) * 0.5;\n\t\t\t\t#endif\n\t\t\t\tvec2 far = vec2(origin.x < (g.x - 1.0) * 0.5 ? g.x - 1.0 : 0.0, origin.y < (g.y - 1.0) * 0.5 ? g.y - 1.0 : 0.0);\n\t\t\t\tfloat mx = distance(far, origin);\n\t\t\t\tfloat mn = distance(clamp(floor(origin + 0.5), vec2(0.0), g - 1.0), origin);\n\t\t\t\tfloat f = mx > mn ? (distance(cell, origin) - mn) / (mx - mn) : 0.0;\n\t\t\t\t#ifdef SF_EDGES\n\t\t\t\treturn 1.0 - f;\t//edges = the inverse of center\n\t\t\t\t#elif defined(SF_START) || defined(SF_END) || defined(SF_MID)\n\t\t\t\treturn f;\n\t\t\t\t#else\n\t\t\t\treturn staggerFrom > 2.5 ? 1.0 - f : f;\t//edges = the inverse of center\n\t\t\t\t#endif\n\t\t\t}\n\t\t\t//per-cell ease (a globally eased driver would warp staggered cells). easeId = family*10 + mode (0 in,\n\t\t\t//1 out, 2 inOut); families 0 linear, 1..4 power1..4, 5 sine, 6 expo, 7 circ, 8 back, 9 bounce.\n\t\t\t//Only the families a transition actually uses are compiled. POWEXP goes further: with one power family in play\n\t\t\t//the exponent is a literal, so FXC folds pow() into multiplies instead of emitting exp2/log2 with a runtime\n\t\t\t//exponent — and this whole function is inlined into every unrolled cell of the neighbour sweep.\n\t\t\tfloat easeInF(float t, float f) {\n\t\t\t\t#ifdef POWEXP\n\t\t\t\treturn pow(t, POWEXP);\n\t\t\t\t#else\n\t\t\t\t#if defined(EF1) || defined(EF2) || defined(EF3) || defined(EF4)\n\t\t\t\tif (f < 4.5) return pow(t, f + 1.0);\n\t\t\t\t#endif\n\t\t\t\t#ifdef EF5\n\t\t\t\tif (f < 5.5) return 1.0 - cos(t * 1.5707963);\n\t\t\t\t#endif\n\t\t\t\t#ifdef EF6\n\t\t\t\tif (f < 6.5) return t <= 0.0 ? 0.0 : pow(2.0, 10.0 * (t - 1.0));\n\t\t\t\t#endif\n\t\t\t\t#ifdef EF7\n\t\t\t\tif (f < 7.5) return 1.0 - sqrt(max(0.0, 1.0 - t * t));\n\t\t\t\t#endif\n\t\t\t\t#ifdef EF8\n\t\t\t\tif (f < 8.5) return t * t * (2.70158 * t - 1.70158);\n\t\t\t\t#endif\n\t\t\t\t#ifdef EF9\n\t\t\t\tfloat u = 1.0 - t;\t//bounce.in = 1 - bounce.out(1-t)\n\t\t\t\tfloat b = u < 0.363636 ? 7.5625 * u * u : u < 0.727272 ? 7.5625 * (u -= 0.545454) * u + 0.75 : u < 0.909090 ? 7.5625 * (u -= 0.818181) * u + 0.9375 : 7.5625 * (u -= 0.954545) * u + 0.984375;\n\t\t\t\treturn 1.0 - b;\n\t\t\t\t#endif\n\t\t\t\treturn t;\n\t\t\t\t#endif\n\t\t\t}\n\t\t\tfloat easeCell(float t, float id) {\n\t\t\t\tif (id < 9.5) return t;\t\t\t\t\t\t\t\t\t\t\t\t//id 0 = linear (no family encodes below 10)\n\t\t\t\tfloat f = floor(id / 10.0 + 0.001), m = mod(id, 10.0);\t\t\t\t//family, mode\n\t\t\t\tif (m < 0.5) return easeInF(t, f);\n\t\t\t\tif (m < 1.5) return 1.0 - easeInF(1.0 - t, f);\n\t\t\t\treturn t < 0.5 ? 0.5 * easeInF(2.0 * t, f) : 1.0 - 0.5 * easeInF(2.0 - 2.0 * t, f);\n\t\t\t}\n\t\t\t//a box's staggered+eased progress (= eased p at grid 1x1 / stagger 0)\n\t\t\tfloat boxProg(vec2 k, vec2 g, float p, float eid) {\n\t\t\t\tfloat delay = cellDelayN(k, g) * stagger;\n\t\t\t\treturn easeCell(clamp((p - delay) / max(1.0 - stagger, 0.0001), 0.0, 1.0), eid);\n\t\t\t}\n\t\t\t#endif\n\n\t\t\t//ONE BOX: cell k's slice, scaled/rotated around the box's OWN moving centre (the displacement is NOT\n\t\t\t//scaled). suv may lie OUTSIDE cell k (m:false = a free sprite). At grid 1x1 this is the whole frame.\n\t\t\tvec4 boxSample(sampler2D tex, vec2 g, vec2 suv, vec2 k, vec2 offC, vec2 scl, float ang, float op) {\n\t\t\t\tvec2 cellSize = 1.0 / g;\n\t\t\t\tvec2 org = k * cellSize;\n\t\t\t\tvec2 local = (suv - org) / cellSize;\t\t\t\t\t\t\t//slot-space position (outside 0..1 when suv is a neighbour's pixel)\n\t\t\t\t#ifdef NOROT\n\t\t\t\tvec2 cUv = (local - 0.5 - offC) / max(scl, vec2(0.0001)) + 0.5;\t//no rotation in this transition -> no sin/cos per cell\n\t\t\t\t#else\n\t\t\t\tvec2 cUv = unrotate(local - 0.5 - offC, ang, aspect * (g.y / g.x)) / max(scl, vec2(0.0001)) + 0.5;\n\t\t\t\t#endif\n\t\t\t\t//Epsilon on the inside test: dense grids (Gradient strips) otherwise drop 1px seams at cell edges from float error.\n\t\t\t\tfloat eps = 0.001;\n\t\t\t\tfloat inside = step(-eps, cUv.x) * step(cUv.x, 1.0 + eps) * step(-eps, cUv.y) * step(cUv.y, 1.0 + eps);\n\t\t\t\tvec4 c = TEXTURE2D(tex, org + clamp(cUv, 0.0, 1.0) * cellSize);\t//clamp UV so the epsilon does not sample a neighbour cell\n\t\t\t\tc.a *= max(op, 0.0) * inside;\n\t\t\t\treturn c;\n\t\t\t}\n\n\t\t\t//ONE cell of the coming side. Without GRID the cell IS the frame, so cp collapses to the raw progress and\n\t\t\t//the driver's own ease carries the timing.\n\t\t\tvec4 comingCell(vec2 suv, vec2 g, vec2 k, float lp, float ico) {\n\t\t\t\t#ifdef GRID\n\t\t\t\tfloat cp = boxProg(k, g, lp, easeId);\n\t\t\t\t#else\n\t\t\t\tfloat cp = lp;\n\t\t\t\t#endif\n\t\t\t\tvec2 offK; float rotK; vec2 sclK;\n\t\t\t\t#ifdef VAR\n\t\t\t\tvarSet(k, g, 0.0, inOff, inRot, inScale, offK, rotK, sclK);\n\t\t\t\t#else\n\t\t\t\toffK = inOff; rotK = inRot; sclK = inScale;\n\t\t\t\t#endif\n\t\t\t\treturn boxSample(src2, g, suv, k, offK * g * (1.0 - cp), mix(sclK, vec2(1.0), cp), rotK * (1.0 - cp), mix(ico, 1.0, cp));\n\t\t\t}\n\t\t\tvec4 leavingCell(vec2 suv, vec2 g, vec2 k, float pv, float oco) {\n\t\t\t\t#ifdef GRID\n\t\t\t\tfloat cp = boxProg(k, g, pv, easeIdOut);\n\t\t\t\t#else\n\t\t\t\tfloat cp = pv;\n\t\t\t\t#endif\n\t\t\t\tvec2 offK; float rotK; vec2 sclK;\n\t\t\t\t#ifdef VAR\n\t\t\t\tvarSet(k, g, 1.0, outOff, outRot, outScale, offK, rotK, sclK);\n\t\t\t\t#else\n\t\t\t\toffK = outOff; rotK = outRot; sclK = outScale;\n\t\t\t\t#endif\n\t\t\t\treturn boxSample(src1, g, suv, k, offK * g * cp, mix(vec2(1.0), sclK, cp), rotK * cp, mix(1.0, oco, cp));\n\t\t\t}\n\n\t\t\t//COMING: the in-state (0) -> identity (1). inR 0 = the single-cell fast path; inR>0 = m:false travelling\n\t\t\t//boxes, composited in the canvas draw order (column-major ascending, later over earlier).\n\t\t\tvec4 sampleComing(vec2 suv, float p) {\n\t\t\t\t#ifdef GRID\n\t\t\t\tvec2 g = max(grid, vec2(1.0));\n\t\t\t\t#else\n\t\t\t\tvec2 g = vec2(1.0);\n\t\t\t\t#endif\n\t\t\t\t#ifdef THRU\n\t\t\t\t//through: ico = 0 so the coming ALWAYS fades in FROM the colour, even if the preset left in.o at 1.\n\t\t\t\tbool thru3 = through > 0.5;\n\t\t\t\tfloat ico = thru3 ? 0.0 : inOp;\n\t\t\t\t//Phase split of the LINEAR driver: leaving OUT [0 .. 0.48], colour HOLD, coming IN [0.55 .. 1]. Geometric\n\t\t\t\t//~48/7/45 reads as ~40/20/40 because the fades bleed. TWO KNOBS: this 0.55 + the 0.48 below.\n\t\t\t\tfloat tIn = thru3 ? 0.55 : thruIn;\n\t\t\t\tfloat lp = thru3 ? clamp((p - tIn) / max(1.0 - tIn, 0.0001), 0.0, 1.0) : p;\n\t\t\t\t#else\n\t\t\t\tfloat ico = inOp;\n\t\t\t\tfloat lp = p;\n\t\t\t\t#endif\n\t\t\t\tvec2 own = floor(clamp(suv, vec2(0.0), vec2(0.9999)) * g);\n\t\t\t\t//GRIDN = the neighbour loop, separate from GRID: m:true cells stay inside their slot (_boxR -> 0), so a\n\t\t\t\t//per-cell preset needs the grid maths but NOT this 11x11 sweep — and that is the loop FF/ANGLE unrolls.\n\t\t\t\t#ifdef GRIDN\n\t\t\t\tif (inR >= 0.5) {\n\t\t\t\t\tvec4 acc = vec4(0.0);\t\t\t\t\t\t\t\t\t\t\t//premultiplied accumulator\n\t\t\t\t\tfor (int dx = -GRIDRX; dx <= GRIDRX; dx++)\n\t\t\t\t\tfor (int dy = -GRIDRY; dy <= GRIDRY; dy++) {\n\t\t\t\t\t\tif (abs(float(dx)) > inR + 0.1 || abs(float(dy)) > inR + 0.1) continue;\n\t\t\t\t\t\tvec2 k = own + vec2(float(dx), float(dy));\n\t\t\t\t\t\tif (k.x < -0.1 || k.y < -0.1 || k.x > g.x - 0.9 || k.y > g.y - 0.9) continue;\n\t\t\t\t\t\tvec4 c = comingCell(suv, g, k, lp, ico);\n\t\t\t\t\t\tacc = vec4(c.rgb * c.a + acc.rgb * (1.0 - c.a), c.a + acc.a * (1.0 - c.a));\n\t\t\t\t\t}\n\t\t\t\t\tif (acc.a > 0.0001) acc.rgb /= acc.a;\n\t\t\t\t\treturn acc;\n\t\t\t\t}\n\t\t\t\t#endif\n\t\t\t\treturn comingCell(suv, g, own, lp, ico);\n\t\t\t}\n\t\t\t//LEAVING: identity (0) -> the out-state (1), on its OWN grid (gridOut) and ease (easeIdOut). through spans\n\t\t\t//the WHOLE duration — the driver extension slows it, so no remap here.\n\t\t\tvec4 sampleLeaving(vec2 suv, float p) {\n\t\t\t\t#ifdef GRID\n\t\t\t\tvec2 g = max(gridOut, vec2(1.0));\n\t\t\t\t#else\n\t\t\t\tvec2 g = vec2(1.0);\n\t\t\t\t#endif\n\t\t\t\t#ifdef THRU\n\t\t\t\t//oco = 0 so the leaving ALWAYS fades to the colour, even when the preset left out.o at 1.\n\t\t\t\tbool thru3 = through > 0.5;\n\t\t\t\tfloat oco = thru3 ? 0.0 : outOp;\n\t\t\t\tfloat pv = thru3 ? clamp(p / 0.48, 0.0, 1.0) : p;\t\t//the leaving finishes its OUT by p=0.48 (see sampleComing)\n\t\t\t\t#else\n\t\t\t\tfloat oco = outOp;\n\t\t\t\tfloat pv = p;\n\t\t\t\t#endif\n\t\t\t\tvec2 own = floor(clamp(suv, vec2(0.0), vec2(0.9999)) * g);\n\t\t\t\t#ifdef GRIDN\n\t\t\t\tif (outR >= 0.5) {\n\t\t\t\t\tvec4 acc = vec4(0.0);\t\t\t\t\t\t\t\t\t\t\t//premultiplied accumulator\n\t\t\t\t\tfor (int dx = -GRIDRX; dx <= GRIDRX; dx++)\n\t\t\t\t\tfor (int dy = -GRIDRY; dy <= GRIDRY; dy++) {\n\t\t\t\t\t\tif (abs(float(dx)) > outR + 0.1 || abs(float(dy)) > outR + 0.1) continue;\n\t\t\t\t\t\tvec2 k = own + vec2(float(dx), float(dy));\n\t\t\t\t\t\tif (k.x < -0.1 || k.y < -0.1 || k.x > g.x - 0.9 || k.y > g.y - 0.9) continue;\n\t\t\t\t\t\tvec4 c = leavingCell(suv, g, k, pv, oco);\n\t\t\t\t\t\tacc = vec4(c.rgb * c.a + acc.rgb * (1.0 - c.a), c.a + acc.a * (1.0 - c.a));\n\t\t\t\t\t}\n\t\t\t\t\tif (acc.a > 0.0001) acc.rgb /= acc.a;\n\t\t\t\t\treturn acc;\n\t\t\t\t}\n\t\t\t\t#endif\n\t\t\t\treturn leavingCell(suv, g, own, pv, oco);\n\t\t\t}\n\t\t\t//2-stage blur: COMINGSRC reads the pre-composited coming from tComingRT (un-premultiplied), so every disc tap\n\t\t\t//below is one fetch instead of a re-run of the neighbour sweep. Without the define this is sampleComing itself.\n\t\t\tvec4 comingAt(vec2 uv, float p) {\n\t\t\t\t#ifdef COMINGSRC\n\t\t\t\tvec4 c = TEXTURE2D(tComingRT, uv); return c.a > 0.0001 ? vec4(c.rgb / c.a, c.a) : vec4(0.0);\n\t\t\t\t#else\n\t\t\t\treturn sampleComing(uv, p);\n\t\t\t\t#endif\n\t\t\t}\n\t\t\t#ifdef MB\n\t\t\t//Integrate the image over the shutter (mbAmt), reusing sampleComing/sampleLeaving so any slide/zoom/rotation/grid blurs. Premultiplied avg = soft alpha edges.\n\t\t\tvec4 comingMB(vec2 uv, float p) {\n\t\t\t\tif (mbAmt <= 0.0001) return comingAt(uv, p);\n\t\t\t\tvec4 acc = vec4(0.0); float taps = max(mbTaps, 1.0);\n\t\t\t\tfor (int i = 0; i < MBTAPS; i++) { if (float(i) >= taps) break;\n\t\t\t\t\tvec4 c = comingAt(uv, clamp(p + ((float(i) + 0.5) / taps - 0.5) * mbAmt, 0.0, 1.0));\n\t\t\t\t\tacc += vec4(c.rgb * c.a, c.a); }\n\t\t\t\tacc /= taps; if (acc.a > 0.0001) acc.rgb /= acc.a; return acc;\n\t\t\t}\n\t\t\tvec4 leavingMB(vec2 uv, float p) {\n\t\t\t\tif (mbAmt <= 0.0001 || hasLeaving < 0.5) return sampleLeaving(uv, p);\n\t\t\t\tvec4 acc = vec4(0.0); float taps = max(mbTaps, 1.0);\n\t\t\t\tfor (int i = 0; i < MBTAPS; i++) { if (float(i) >= taps) break;\n\t\t\t\t\tvec4 c = sampleLeaving(uv, clamp(p + ((float(i) + 0.5) / taps - 0.5) * mbAmt, 0.0, 1.0));\n\t\t\t\t\tacc += vec4(c.rgb * c.a, c.a); }\n\t\t\t\tacc /= taps; if (acc.a > 0.0001) acc.rgb /= acc.a; return acc;\n\t\t\t}\n\t\t\t#endif\n\n\t\t\tvoid main() {\n\t\t\t\tfloat p = clamp(progress, 0.0, 1.0);\n\t\t\t\t#ifdef DOUBLE\n\t\t\t\t//Double Parallax: the LEAVING (src1) under, the COMING (src2) over with a darkened GHOST in a sweeping\n\t\t\t\t//band. Its own algorithm — none of the transform maths above applies. hasLeaving=0 => transparent under.\n\t\t\t\tif (dbl > 0.5) {\n\t\t\t\t\tbool  axisX = abs(inOff.x) >= abs(inOff.y);\n\t\t\t\t\tfloat a     = axisX ? vUv.x : vUv.y;\n\t\t\t\t\tfloat dir   = (inOff.x + inOff.y >= 0.0) ? 1.0 : -1.0;\n\t\t\t\t\tvec2  dv    = axisX ? vec2(dir, 0.0) : vec2(0.0, dir);\t\t\t\t//signed flow axis (everything moves along -dv; the coming enters from +dv edge)\n\t\t\t\t\tfloat e     = (dir > 0.0) ? a : (1.0 - a);\t\t\t\t\t\t\t//\"entering-normalised\": e=1 at the entering edge, e=0 at the far edge\n\t\t\t\t\t//COMING main: the full-colour OPAQUE copy (canvas draws it at o:-1). MASKED to the swept region so it stays\n\t\t\t\t\t//invisible ahead of the ghost — the ghost's trailing edge (Lb) reveals it at full opacity, never a fade.\n\t\t\t\t\tfloat Lb    = max(0.0, 1.0 - 2.0 * p);\n\t\t\t\t\tfloat Rb    = min(1.0, Lb + 2.0 * (1.0 - p));\n\t\t\t\t\tvec2  mUv   = vUv - dv * (dblDrift * (1.0 - p));\n\t\t\t\t\tvec4  mainC = TEXTURE2D(src2, mUv);\n\t\t\t\t\tfloat mIn   = step(0.0, mUv.x) * step(mUv.x, 1.0) * step(0.0, mUv.y) * step(mUv.y, 1.0);\n\t\t\t\t\tfloat mainA = mIn * smoothstep(Lb - dblEdge, Lb + dblEdge, e);\n\t\t\t\t\t//GHOST: a 2nd, more-offset, DARKENED copy, masked to the band Lb..Rb (width 2*(1-p)), over the main.\n\t\t\t\t\tvec3  ghostC = TEXTURE2D(src2, vUv - dv * (dblGhostDrift * (1.0 - 2.0 * p))).rgb * dblGhostDark;\n\t\t\t\t\tfloat band  = smooth